CREATE TABLE return_credit_requests(id BIGINT PRIMARY KEY AUTO_INCREMENT,dispense_id BIGINT NOT NULL,invoice_id BIGINT NOT NULL,amount DECIMAL(12,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'PENDING',reason VARCHAR(500) NOT NULL,requested_by VARCHAR(80) NOT NULL,reconciled_by VARCHAR(80),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(dispense_id) REFERENCES pharmacy_dispenses(id),FOREIGN KEY(invoice_id) REFERENCES invoices(id));
